window.BFM = window.BFM || {};
window.BFM.generatedContent = "<a class=\"skip-link\" href=\"#main-content\">本文へスキップ</a>\n<div class=\"reading-progress\" role=\"progressbar\" aria-label=\"ページ内の学習進捗\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\"><span id=\"reading-progress-bar\" aria-hidden=\"true\"></span></div>\n\n<header class=\"site-header\" id=\"top\">\n    <a class=\"brand\" href=\"#top\" aria-label=\"BFM Japan トップへ\">\n      <span class=\"brand-mark\" aria-hidden=\"true\">B</span>\n      <span><strong>BFM Japan</strong><small>FLIGHT GEOMETRY / 01</small></span>\n    </a>\n    <button class=\"menu-toggle\" id=\"menu-toggle\" type=\"button\" aria-expanded=\"false\" aria-controls=\"global-nav\" aria-label=\"メニューを開く\">\n      <span></span><span></span><span></span>\n    </button>\n    <nav class=\"global-nav\" id=\"global-nav\" aria-label=\"メインナビゲーション\">\n      <a href=\"#overview\">BFM入門</a>\n      <a href=\"#course-offensive\">Offensive BFM</a>\n      <a href=\"#course-defensive\">Defensive BFM</a>\n    </nav>\n    <details class=\"mission-index-menu\" id=\"mission-index-menu\">\n      <summary class=\"toc-toggle\" aria-label=\"学習目次を開く\">\n        <span class=\"toc-toggle-title\">目次</span>\n      </summary>\n      <nav class=\"mission-index-panel\" id=\"mission-index-panel\" aria-label=\"ページ内の学習目次\">\n        <div class=\"mission-index-heading\">\n          <div><span>MISSION INDEX</span><strong>学習目次</strong></div>\n          <button class=\"toc-close\" id=\"toc-close\" type=\"button\" aria-label=\"学習目次を閉じる\"><span aria-hidden=\"true\"></span></button>\n        </div>\n        <ol class=\"mission-index-list\">\n          <li><a href=\"#overview\"><span>01</span>BFMとは何か</a></li>\n          <li><a href=\"#roadmap\"><span>02</span>基礎講座の進め方</a></li>\n          <li><a href=\"#principles\"><span>03</span>BFMの3原則</a></li>\n          <li><a href=\"#energy\"><span>04</span>旋回とエネルギー</a></li>\n          <li><a href=\"#turn-performance\"><span>05</span>Turn Rate / Radius</a></li>\n          <li><a href=\"#geometry\"><span>06</span>2機の位置関係</a></li>\n          <li><a href=\"#turn-circle\"><span>07</span>Turning Room / Circle</a></li>\n          <li><a href=\"#pursuit\"><span>08</span>Pursuit Curves</a></li>\n          <li><a href=\"#overshoot\"><span>09</span>Overshoot</a></li>\n          <li><a href=\"#alignment\"><span>10</span>Circle Alignment</a></li>\n          <li><a href=\"#circle-fight\"><span>11</span>One / Two Circle</a></li>\n          <li><a href=\"#plane-motion\"><span>12</span>Plane of Motion</a></li>\n          <li><a href=\"#guns\"><span>13</span>射撃機会の基礎</a></li>\n          <li><a href=\"#recap\"><span>14</span>初心者の要点</a></li>\n          <li><a href=\"#quiz\"><span>15</span>確認問題</a></li>\n          <li><a href=\"#glossary\"><span>16</span>用語集</a></li>\n          <li><a href=\"#references\"><span>17</span>参考資料・出典</a></li>\n          <li><a href=\"#next\"><span>18</span>Next Part</a></li>\n        </ol>\n        <div class=\"index-progress\" role=\"progressbar\" aria-label=\"ページ内の学習進捗\" aria-valuemin=\"0\" aria-valuemax=\"100\" aria-valuenow=\"0\">\n          <span>PAGE PROGRESS</span>\n          <strong id=\"progress-percent\">0%</strong>\n        </div>\n      </nav>\n    </details>\n  </header>\n\n<main id=\"main-content\">\n  <section class=\"welcome-sequence\" id=\"welcome\" aria-labelledby=\"welcome-title\">\n        <div class=\"welcome-sticky\">\n          <div class=\"welcome-grid\" aria-hidden=\"true\"></div>\n          <div class=\"welcome-stage\">\n            <p class=\"welcome-message welcome-message-primary\" id=\"welcome-title\" data-welcome-step=\"1\"><span>ようこそ</span><span>BFM Japanへ</span></p>\n            <p class=\"welcome-message welcome-message-secondary\" data-welcome-step=\"2\">ここではドックファイトにおいて必要なBFMを学ぶことができます</p>\n          </div>\n          <p class=\"welcome-scroll-cue\" aria-hidden=\"true\"><span></span>SCROLL</p>\n        </div>\n      </section>\n\n  <section class=\"hero\" aria-labelledby=\"hero-title\">\n        <div class=\"hero-grid\"></div>\n        <div class=\"hero-copy\">\n          <p class=\"kicker hero-part-label\">PART 1:</p>\n          <h1 id=\"hero-title\"><span class=\"hero-title-main\"><span class=\"hero-title-phrase\">BFMを、</span><span class=\"hero-title-phrase\">迷わず学ぶ</span></span></h1>\n          <p class=\"hero-definition\">BFMを学び始めると、英語の専門用語や断片的な解説が先に現れ、<strong>何を、どの順番で理解すればよいか</strong>が見えにくくなります。</p>\n          <div class=\"creator-info info-stack\">\n            <p class=\"creator-note\"><span>制作背景</span>このサイトは、製作者自身がBFMを学ぶ過程で、散在する用語や考え方を一つの流れに整理するためのまとめノートとして制作しました。同じようにBFMを学び始める人にも役立てばと思い公開しています。</p>\n            <p class=\"hero-purpose\"><span>サイトの目的</span>日本人の初心者が、定義・位置関係・エネルギーを順序立てて学び、出典を確かめながら、自分の言葉でBFMを説明できるようになることです。</p>\n            <p class=\"creator-note creator-request\"><span>お願い</span>本サイトは初心者が初心者のためにつくりました。間違っている箇所があるかもしれませんが、ご容赦ください。</p>\n          </div>\n          <div class=\"hero-actions\">\n            <a class=\"button button-primary\" href=\"#overview\">入門講座を始める <span aria-hidden=\"true\">↘</span></a>\n            <a class=\"button button-quiet\" href=\"#roadmap\">学習順を見る</a>\n          </div>\n        </div>\n        <aside class=\"hero-briefing\" aria-labelledby=\"hero-loop-title\">\n          <header><span>LEARNING DESIGN</span><strong id=\"hero-loop-title\">3 PROMISES</strong></header>\n          <dl>\n            <div><dt><span>01</span>Start with Why</dt><dd>技の名前より先に、意味と目的を知る</dd></div>\n            <div><dt><span>02</span>Step by Step</dt><dd>前提となる用語を、順序立てて学ぶ</dd></div>\n            <div><dt><span>03</span>Check Sources</dt><dd>図や重要な説明の根拠を確認できる</dd></div>\n          </dl>\n          <p><span>KEY IDEA</span> 基礎を終えたら、次に学ぶ講座を自分で選びます。</p>\n        </aside>\n        <div class=\"scroll-cue\" aria-hidden=\"true\"><span></span>SCROLL TO BRIEF</div>\n      </section>\n\n  <div class=\"page-shell\" id=\"page-shell\">\n    <article class=\"learning-content\">\n      <section class=\"mission-sequence\" id=\"overview\" data-section=\"BFMとは何か\" aria-labelledby=\"overview-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>01</span></p>\n              <p class=\"mission-reveal-title\">BFMとは何か</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"overview-title\">\n          <header class=\"module-header lesson-header\">\n            <div>\n              <h2 class=\"numbered-module-title lesson-title\" id=\"overview-title\"><span class=\"module-title-number lesson-number\">01:</span><span class=\"module-title-text lesson-title-text\">BFMとは何か</span></h2>\n            </div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>BFMを「技の暗記」ではなく、相対位置を継続して整える判断の体系として説明できる。</p>\n          </header>\n          <div class=\"term-title\">\n            <p class=\"term-en\">Basic Fighter Maneuvers</p>\n            <p class=\"term-ja\">基本戦闘機動</p>\n          </div>\n          <p class=\"lead-copy\">BFMは、決められた機動を順番に実行する台本ではありません。相手との位置関係を<strong>観察し、次の変化を予測し、必要な機動を選ぶ</strong>——この判断を繰り返しながら、自機を必要な位置へ動かすための基礎です。<a class=\"source-marker\" href=\"#ref-1\" aria-label=\"参考資料1へ\">[1]</a></p>\n          <p>成功に必要なのは、単一の技名ではなく、2機の幾何学的な関係、旋回性能、エネルギー、そして飛行の基本原理を一緒に読むことです。状況が変われば、選ぶ機動も変わります。</p>\n\n          <div class=\"subsection\" id=\"bfm-purpose\">\n            <p class=\"eyebrow\">WHY BFM EXISTS</p>\n            <h3>必要な位置を作り、相手には同じ条件を作らせない</h3>\n            <p>目標は、単に「相手の後ろに見える場所」へ行くことではありません。距離・角度・接近率が使える範囲に収まる位置を作り、その関係を維持します。同時に、相手が同じ条件を得ることは難しくします。</p>\n            <div class=\"comparison-cards card-grid two-up purpose-comparison\">\n              <article><span class=\"compare-tag\">CREATE</span><h4>自機の機会を作る</h4><p>相手との距離と角度を整え、次の判断に使える時間と空間を確保します。</p></article>\n              <article><span class=\"compare-tag warning\">DENY</span><h4>相手の機会を減らす</h4><p>相手の機首・飛行経路・エネルギーを見て、一方的に有利な条件を作らせません。</p></article>\n            </div>\n          </div>\n\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">WHAT TO MANAGE</p>\n            <h3>読み続ける3つの判断軸</h3>\n            <div class=\"triad card-grid\">\n              <article><span>01</span><h4>Range</h4><p>2機の距離。近すぎるか、遠すぎるかを見ます。</p></article>\n              <article><span>02</span><h4>Angles</h4><p>位置と向きの関係。1種類の角度ではありません。</p></article>\n              <article><span>03</span><h4>Closure</h4><p>距離が変化する速さ。接近・一定・離隔を見ます。</p></article>\n            </div>\n            <h3 class=\"flow-heading\">判断軸をもとにした戦闘時の思考フロー</h3>\n            <div class=\"triangle-flow\" role=\"img\" aria-label=\"01 観察する、02 変化を予測する、03 機動を選ぶ、そして01へ戻る循環\">\n              <svg viewBox=\"0 0 640 440\" aria-hidden=\"true\" focusable=\"false\">\n                <defs><marker id=\"flow-arrow\" viewBox=\"0 0 10 10\" refX=\"8\" refY=\"5\" markerWidth=\"8\" markerHeight=\"8\" orient=\"auto-start-reverse\"><path d=\"M 0 0 L 10 5 L 0 10 z\"></path></marker></defs>\n                <path d=\"M 350 90 Q 520 125 505 300\"></path>\n                <path d=\"M 455 340 Q 320 420 185 340\"></path>\n                <path d=\"M 135 300 Q 120 125 290 90\"></path>\n              </svg>\n              <ol>\n                <li class=\"flow-node flow-observe\"><span>01</span><strong>観察する</strong></li>\n                <li class=\"flow-node flow-predict\"><span>02</span><strong>変化を予測する</strong></li>\n                <li class=\"flow-node flow-act\"><span>03</span><strong>機動を選ぶ</strong></li>\n              </ol>\n              <p><strong>03から01へ戻る</strong><span>機動後の状況を、もう一度観察します。</span></p>\n            </div>\n            <div class=\"warning-box callout callout-warning\"><span>注意</span><p>どれか1つだけでは判断できません。後方に見えても、距離が詰まりすぎていたり、相手がこちらへ向き直れる角度なら、維持できる位置とは限りません。</p></div>\n          </div>\n\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>BFMは固定手順ではありません。観察・予測・機動を循環させ、変化する2機の関係を整えるために存在します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"roadmap\" data-section=\"基礎の学習順\" aria-labelledby=\"roadmap-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>02</span></p>\n              <p class=\"mission-reveal-title\">基礎講座の進め方</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"roadmap-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"roadmap-title\"><span class=\"module-title-number lesson-number\">02:</span><span class=\"module-title-text lesson-title-text\">基礎講座の進め方</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>このページで身につける基礎を、5つの段階で把握する。</p>\n          </header>\n          <p class=\"lead-copy\">用語をばらばらに暗記せず、「目的」から「確認問題」まで順に進みます。各章の最後にある要点を、自分の言葉で説明できるか確かめてください。</p>\n          <ol class=\"fundamentals-path\">\n            <li><span>01</span><div><h3>目的と原則を知る</h3><p>BFMが何を解決し、何を判断の軸にするのか。</p></div><a href=\"#principles\">3つの原則へ</a></li>\n            <li><span>02</span><div><h3>性能を知る</h3><p>旋回とエネルギー、RateとRadiusの違い。</p></div><a href=\"#energy\">エネルギーへ</a></li>\n            <li><span>03</span><div><h3>関係を読む</h3><p>Range・Angles・ClosureとTurn Circle。</p></div><a href=\"#geometry\">位置関係へ</a></li>\n            <li><span>04</span><div><h3>流れを判断する</h3><p>Pursuit・Overshoot・Circle・運動面。</p></div><a href=\"#pursuit\">追跡へ</a></li>\n            <li><span>05</span><div><h3>理解を確認する</h3><p>要点を整理し、確認問題に答える。</p></div><a href=\"#quiz\">確認問題へ</a></li>\n          </ol>\n          <div class=\"checkpoint callout callout-summary\"><strong>進め方</strong><p>基礎講座を最後まで終えたあとに、ページ最下部で次に学ぶ講座を選びます。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"principles\" data-section=\"BFMの3原則\" aria-labelledby=\"principles-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>03</span></p>\n              <p class=\"mission-reveal-title\">BFMの3原則</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"principles-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"principles-title\"><span class=\"module-title-number lesson-number\">03:</span><span class=\"module-title-text lesson-title-text\">BFMの3原則</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>視認・相対関係・エネルギーの3視点を、具体例と結びつける。</p>\n          </header>\n          <div class=\"principle-grid card-grid\">\n            <article class=\"principle-card\">\n              <span class=\"card-number\">01</span>\n              <h3>Lose sight,<br>lose the fight.</h3>\n              <p class=\"translation\">見失えば、戦いを見失う。</p>\n              <p>敵機を見失うと、位置変化や次の行動を予測できません。計器だけでなく、操縦しながら相手との位置関係を継続して確認します。</p>\n              <div class=\"example\"><b>例</b><p>速度計を見た数秒の間に、敵機が旋回方向を変えた。視線を戻したとき、次に探す方向が分からなくなる。</p></div>\n            </article>\n            <article class=\"principle-card\">\n              <span class=\"card-number\">02</span>\n              <h3>Maneuver relative<br>to the bandit.</h3>\n              <p class=\"translation\">敵機との相対関係で機動する。</p>\n              <p>自機が水平か垂直かだけでは判断しません。敵機の旋回方向と動きに対応し、必要なら相手のミスを誘うように機動します。</p>\n              <div class=\"example\"><b>用語</b><p><strong>bandit（バンディット）</strong>は「敵機」を意味します。同じ右旋回でも相手の位置で意味が変わります。</p></div>\n            </article>\n            <article class=\"principle-card\">\n              <span class=\"card-number\">03</span>\n              <h3>Energy versus<br>nose position.</h3>\n              <p class=\"translation\">エネルギーと機首位置のバランス。</p>\n              <p>強く旋回すれば早く機首を向けられますが、速度を失います。一方、高速すぎると旋回半径が大きくなる場合があります。</p>\n              <div class=\"example\"><b>例</b><p>いま射撃機会が生まれるなら速度を使う。まだ距離があるなら、旋回を緩めてエネルギーを温存する。</p></div>\n            </article>\n          </div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>「見続ける」「相手を基準に考える」「エネルギーと機首位置を交換する」。この3つが、以降の比較や操作結果を読む軸です。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"energy\" data-section=\"旋回とエネルギー\" aria-labelledby=\"energy-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>04</span></p>\n              <p class=\"mission-reveal-title\">旋回とエネルギー</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"energy-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"energy-title\"><span class=\"module-title-number lesson-number\">04:</span><span class=\"module-title-text lesson-title-text\">旋回とエネルギー</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>操縦入力・迎角・揚力・抗力・速度のつながりを説明できる。</p>\n          </header>\n          <div class=\"force-layout\">\n            <div>\n              <p class=\"lead-copy\">航空機のエネルギー状態（energy state）は、主に<strong>速度と高度</strong>として考えます。操縦桿を引くと迎角が増え、旋回に必要な揚力を得ますが、同時に抗力も増えます。<a class=\"source-marker\" href=\"#ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n              <div class=\"term-chips\" aria-label=\"基本用語\">\n                <span><b>lift</b> 揚力</span><span><b>drag</b> 抗力</span><span><b>thrust</b> 推力</span>\n                <span><b>angle of attack</b> 迎角</span><span><b>G-force</b> G</span><span><b>load factor</b> 荷重倍数</span>\n                <span><b>stall</b> 失速</span><span><b>airspeed</b> 対気速度</span>\n              </div>\n            </div>\n            <figure class=\"reference-figure\">\n              <div class=\"reference-image-canvas\">\n                <img src=\"assets/reference-nasa-four-forces.jpg\" alt=\"航空機に働く揚力、重量、推力、抗力を矢印で示したNASA Glennの図\" loading=\"lazy\">\n              </div>\n              <figcaption class=\"compact-citation\"><a class=\"source-marker\" href=\"#ref-2\" aria-label=\"参考資料2へ\">[2]</a></figcaption>\n            </figure>\n          </div>\n          <dl class=\"force-definitions\">\n            <div><dt>lift <small>揚力</small></dt><dd>空気の流れから生まれ、機体を支えたり旋回させたりする力。</dd></div>\n            <div><dt>drag <small>抗力</small></dt><dd>空気が機体の進行を妨げる力。強い旋回で増えやすい。</dd></div>\n            <div><dt>thrust <small>推力</small></dt><dd>エンジンなどが機体を前へ進める方向に作る力。</dd></div>\n            <div><dt>angle of attack <small>迎角</small></dt><dd>翼の基準線と、翼に当たる空気の流れとの角度。</dd></div>\n            <div><dt>G-force / load factor <small>G・荷重倍数</small></dt><dd>旋回などで機体へかかる荷重を、重力との比で捉える量。</dd></div>\n            <div><dt>stall <small>失速</small></dt><dd>臨界迎角を超えるなどして気流が剥離し、必要な揚力を保てない状態。</dd></div>\n            <div><dt>airspeed <small>対気速度</small></dt><dd>周囲の空気に対する速度。旋回性能を考える基礎となる。</dd></div>\n            <div><dt>energy state <small>エネルギー状態</small></dt><dd>主に速度と高度の組み合わせとして捉える、機動に使える状態。</dd></div>\n            <div><dt>energy management <small>エネルギー管理</small></dt><dd>速度と高度を、位置取りのために使う・温存する・回復する判断。</dd></div>\n          </dl>\n          <ol class=\"cause-chain\" aria-label=\"操縦桿を引いたときの変化\">\n            <li>操縦桿を引く</li><li>迎角が増える</li><li>揚力が増える</li><li>旋回が強くなる</li><li>抗力も増える</li><li>速度を失いやすい</li>\n          </ol>\n          <p class=\"term-note induced-drag-note\"><strong>Induced Drag（誘導抗力）</strong>は、揚力を生み出すことに伴って生じる抗力です。旋回でより大きな揚力を求めるほど増えやすいため、「強く引く → 揚力が増える → 抗力も増える」というつながりで捉えます。<a class=\"source-marker\" href=\"#ref-2\" aria-label=\"参考資料2へ\">[2]</a></p>\n          <p class=\"small-note\">迎角を増やしすぎると翼上面の気流が剥離し、揚力を保てない<strong>stall（失速）</strong>へ近づきます。強く引くほど常に良い、という関係ではありません。</p>\n\n          <div class=\"limits-grid\">\n            <article>\n              <span class=\"limit-mark low\">LOW SPEED</span>\n              <h3>Lift Limit <small>揚力限界</small></h3>\n              <p>低速域で、現在の状態から生み出せる揚力の上限に近い状態。瞬間的な旋回率を得られますが、抗力が大きく、速度を急速に失います。</p>\n              <p class=\"analogy\">airspeedをturn rateへ交換するイメージ</p>\n            </article>\n            <article>\n              <span class=\"limit-mark rate\">SUSTAINED</span>\n              <h3>Rate Band <small>持続しやすい速度帯</small></h3>\n              <p>高い旋回率を比較的少ない損失で維持しやすい帯域。機体・搭載物・重量・高度で変わるため、固定値として暗記しません。</p>\n              <p class=\"analogy\">速さと旋回を長く両立しやすい領域</p>\n            </article>\n            <article>\n              <span class=\"limit-mark high\">HIGH SPEED</span>\n              <h3>Load Limit <small>荷重限界</small></h3>\n              <p>高速域などで許容最大Gに達した状態。さらに引いても旋回率が大きく伸びず、速度のため旋回半径は大きい場合があります。</p>\n              <p class=\"analogy\">高速＝小さく旋回、ではない</p>\n            </article>\n          </div>\n          <div class=\"bridge-note callout callout-bridge energy-trade-note\"><span>ENERGY TRADE</span><p><strong>Energy Expenditure / Energy Trade</strong>は、速度や高度として持つエネルギーを、短時間の旋回率や機首位置へ交換する考え方です。資料によってEnergy ExertionやEnergy Excursionと表現される場合がありますが、この講座では「何を使い、何を得たか」に注目します。<a class=\"source-marker\" href=\"#ref-1\" aria-label=\"参考資料1へ\">[1]</a></p></div>\n\n          <div class=\"interactive-panel\" id=\"speed-lab\">\n            <div class=\"panel-heading\">\n              <div><p class=\"interactive-label\">COMPARE 01</p><h3>速度域ごとの注意点</h3></div>\n              <p>数値を推定せず、3つの定性的な領域だけを比較します。</p>\n            </div>\n            <div class=\"speed-choice\" role=\"group\" aria-label=\"速度域を選択\">\n              <button type=\"button\" data-speed-region=\"low\" aria-pressed=\"false\"><span>LOW</span><small>Lift Limit</small></button>\n              <button type=\"button\" class=\"is-active\" data-speed-region=\"rate\" aria-pressed=\"true\"><span>RATE BAND</span><small>Best Sustained Area</small></button>\n              <button type=\"button\" data-speed-region=\"high\" aria-pressed=\"false\"><span>HIGH</span><small>Load Limit</small></button>\n            </div>\n            <div class=\"region-readout region-readout-wide\" id=\"speed-region\" aria-live=\"polite\">\n              <span class=\"readout-kicker\">SELECTED REGION</span>\n              <strong id=\"speed-region-name\">Best Sustained Area</strong>\n              <p id=\"speed-region-desc\">高い旋回率を比較的維持しやすい領域です。正確な速度帯は機体・重量・高度・搭載物で変わります。</p>\n              <dl class=\"region-facts\">\n                <div><dt>主な利点</dt><dd id=\"speed-benefit\">旋回率とエネルギー維持の両立</dd></div>\n                <div><dt>主な注意</dt><dd id=\"speed-caution\">固定の速度値として暗記しない</dd></div>\n              </dl>\n            </div>\n          </div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>強い旋回は無料ではありません。低速では失速、高速では大きな半径、中間では持続性——速度域ごとの交換条件を意識します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"turn-performance\" data-section=\"Turn RateとRadius\" aria-labelledby=\"turn-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>05</span></p>\n              <p class=\"mission-reveal-title\">Turn Rate / Radius</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"turn-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"turn-title\"><span class=\"module-title-number lesson-number\">05:</span><span class=\"module-title-text lesson-title-text\">Turn Rate / Radius</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>「向きが変わる速さ」と「円の小ささ」を区別する。</p>\n          </header>\n          <div class=\"two-term-grid card-grid\">\n            <article><span class=\"term-index\">A</span><h3>Turn Rate <small>旋回率</small></h3><p>1秒間に機首方向が何度変わるか。単位例はdegrees per second（度毎秒）。高いほど旋回円上を速く進みます。</p></article>\n            <article><span class=\"term-index\">B</span><h3>Turn Radius <small>旋回半径</small></h3><p>旋回円の中心から機体までの距離。旋回円の直径に対して半分の長さです。小さいほど狭い空間で向きを変えられますが、高速では大きくなる場合があります。<a class=\"source-marker\" href=\"#ref-3\" aria-label=\"参考資料3へ\">[3]</a></p></article>\n          </div>\n          <div class=\"relationship-strip\" aria-label=\"Turn RateとTurn Radiusを混同しないための要点\">\n            <p><span>時間を見る</span><strong>Turn Rate</strong><small>1秒で向きが何度変わるか</small></p>\n            <span class=\"relationship-not-equal\" aria-label=\"同じ意味ではない\">≠</span>\n            <p><span>空間を見る</span><strong>Turn Radius</strong><small>どれだけ狭い円を描くか</small></p>\n          </div>\n          <div class=\"subsection\">\n            <p class=\"eyebrow\">ENERGY CHECK</p>\n            <h3>瞬間旋回と持続旋回を分ける</h3>\n            <div class=\"two-term-grid card-grid\">\n              <article><span class=\"term-index\">I</span><h4>Instantaneous Rate <small>瞬間旋回率</small></h4><p>現在の速度から一時的に作れる高い旋回率。多くの場合は速度・高度として持つエネルギーを消費します。</p></article>\n              <article><span class=\"term-index\">S</span><h4>Sustained Rate <small>持続旋回率</small></h4><p>速度と高度を保ちながら続けられる旋回率。瞬間値より低くても、関係を長く作り続けられます。</p></article>\n            </div>\n            <p class=\"term-note\"><strong>Specific Energy Rate（Ps）</strong>は、機動中にエネルギーが増えているか、減っているかを表す考え方です。ここでは機種固有の数値を使わず、「いまの旋回を続けられるか」を判断する言葉として扱います。<a class=\"source-marker\" href=\"#ref-1\" aria-label=\"参考資料1へ\">[1]</a></p>\n          </div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Rateは「時間あたりの角度」、Radiusは「円の大きさ」。One‑CircleとTwo‑Circleでは、重視される側が変わります。<a class=\"source-marker\" href=\"#ref-3\" aria-label=\"参考資料3へ\">[3]</a></p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"geometry\" data-section=\"2機の位置関係\" aria-labelledby=\"geometry-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>06</span></p>\n              <p class=\"mission-reveal-title\">2機の位置関係</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"geometry-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"geometry-title\"><span class=\"module-title-number lesson-number\">06:</span><span class=\"module-title-text lesson-title-text\">2機の位置関係</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>Range・Aspect Angle・HCA・Closureを混同せず、現在と次の変化を読み取る。</p>\n          </header>\n          <div class=\"concept-columns geometry-concepts\">\n            <article><h3>Range <small>距離</small></h3><p>2機の直線距離。遠すぎれば攻撃できず、近すぎれば追い越す可能性があります。距離だけで有利・不利は決まりません。</p></article>\n            <article><h3>Aspect Angle <small>アスペクト角</small></h3><p>相手の尾部方向から、自機がいる方向までの角度。自機の機首がどこを向くかとは無関係です。0°は真後ろ、90°は横、180°は正面側です。</p></article>\n            <article><h3>Heading Crossing Angle <small>HCA・針路交差角</small></h3><p>2機の進行方向の差。同じ向きなら小さく、正面から向き合うほど180°に近づきます。位置を表すAspect Angleとは別の量です。</p></article>\n            <article><h3>Closure <small>接近率</small></h3><p>距離が変わる速さ。正なら接近、ほぼ0なら一定、負なら離れています。大きすぎるとOvershootしやすくなります。</p></article>\n            <article class=\"geometry-concept-aot\"><h3>Angle Off Tail <small>AOT・尾部方向を基準にした角度</small></h3><p>AOTは、相手の尾部方向を基準に自機の位置を表す語として使われ、Aspect Angleとほぼ同じ意味で扱われる資料があります。一方で、angle-offを2機の機首方位の差、つまりHCAの意味で使う資料もあります。この講座では位置をAspect Angle、機首方位の差をHCAと呼び、資料を読むときは定義を先に確認します。<a class=\"source-marker\" href=\"#ref-4\" aria-label=\"参考資料4へ\">[4]</a></p></article>\n            <article class=\"geometry-concept-ata\"><h3>Antenna Train Angle <small>ATA・自機の機首と視線の角度</small></h3><p>自機の機首方向と相手への視線の角度です。Aspect Angleが「相手から見た自機の位置」なのに対し、ATAは「自機の機首が相手からどれだけ外れているか」を示します。<a class=\"source-marker\" href=\"#ref-4\" aria-label=\"参考資料4へ\">[4]</a><a class=\"source-marker\" href=\"#ref-1\" aria-label=\"参考資料1へ\">[1]</a></p></article>\n          </div>\n          <div class=\"relationship-strip geometry-units\" aria-label=\"RangeとClosureでよく使われる単位\">\n            <p><span>距離を表す</span><strong>Range</strong><small>nm（海里）やft（フィート）など</small></p>\n            <span class=\"relationship-not-equal\" aria-hidden=\"true\">/</span>\n            <p><span>距離の変化率を表す</span><strong>Closure</strong><small>kt（ノット）など</small></p>\n          </div>\n          <p class=\"geometry-table-note\">表示単位は資料やシステムによって変わります。数字だけで読まず、距離なのか距離の変化率なのかを先に確認します。</p>\n          <div class=\"geometry-table-grid\" aria-label=\"位置関係の読み方\">\n            <div class=\"table-wrap\">\n              <table class=\"geometry-reference-table\">\n                <caption>Aspect Angleの目安</caption>\n                <thead><tr><th scope=\"col\">角度</th><th scope=\"col\">自機の位置</th></tr></thead>\n                <tbody>\n                  <tr><th scope=\"row\">0°</th><td>相手の真後ろ</td></tr>\n                  <tr><th scope=\"row\">90°</th><td>相手の横</td></tr>\n                  <tr><th scope=\"row\">180°</th><td>相手の正面側</td></tr>\n                </tbody>\n              </table>\n            </div>\n            <div class=\"table-wrap\">\n              <table class=\"geometry-reference-table\">\n                <caption>Closureの状態</caption>\n                <thead><tr><th scope=\"col\">状態</th><th scope=\"col\">距離の変化</th><th scope=\"col\">見ること</th></tr></thead>\n                <tbody>\n                  <tr><th scope=\"row\">接近</th><td>減る</td><td>詰まり方を監視</td></tr>\n                  <tr><th scope=\"row\">一定</th><td>ほぼ不変</td><td>角度と位置を再確認</td></tr>\n                  <tr><th scope=\"row\">離隔</th><td>増える</td><td>離れすぎに注意</td></tr>\n                </tbody>\n              </table>\n            </div>\n          </div>\n          <p class=\"geometry-table-note\">Aspect Angleだけで有利・不利は決まりません。Range・HCA・ATA・Closureを一緒に読みます。</p>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Aspect Angleは位置、HCAは進行方向の差、ATAは機首と視線の差です。距離と接近率も同時に読み、数秒後の関係を予測します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"turn-circle\" data-section=\"Turn Circle\" aria-labelledby=\"turn-circle-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>07</span></p>\n              <p class=\"mission-reveal-title\">Turning Room / Circle</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"turn-circle-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"turn-circle-title\"><span class=\"module-title-number lesson-number\">07:</span><span class=\"module-title-text lesson-title-text\">Turning Room / Circle</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>向きを変えるために使える空間と、機体が実際に描く旋回円を区別する。</p>\n          </header>\n          <div class=\"turn-circle-learning-flow\">\n            <section class=\"turn-circle-stage\" aria-labelledby=\"turn-circle-foundation-title\">\n              <header class=\"turn-circle-stage-header\">\n                <p class=\"turn-circle-stage-marker\"><span>STEP</span><strong>01</strong><small>FOUNDATION</small></p>\n                <div class=\"topic-heading\"><p class=\"eyebrow\">CORE CONCEPTS</p><h3 id=\"turn-circle-foundation-title\">Turning Roomを理解する3つの基本概念</h3></div>\n              </header>\n              <div class=\"zones-copy\">\n                <article><span>01</span><h3>Turning Room <small>旋回に使える空間</small></h3><p>2機の間にあり、加速・距離調整・角度修正に使える空間です。水平方向だけでなく上下方向にも作れ、どちらの機体も利用できます。</p></article>\n                <article><span>02</span><h3>Turn Circle <small>現在の旋回円</small></h3><p>速度と旋回荷重から生じる旋回の大きさです。地面に固定された円ではなく、速度・G・運動面が変われば中心と大きさも変わります。</p></article>\n                <article><span>03</span><h3>Turn Rate <small>円を進む速さ</small></h3><p>旋回円の周りをどれだけ速く進むかを表します。狭い円を描く能力と、円周上を速く進む能力は同じではありません。</p></article>\n              </div>\n            </section>\n            <section class=\"turn-circle-stage turn-space-model\" id=\"turn-space-model\" aria-labelledby=\"turn-space-model-title\">\n              <header class=\"turn-circle-stage-header\">\n                <p class=\"turn-circle-stage-marker\"><span>STEP</span><strong>02</strong><small>RELATIVE SPACE</small></p>\n                <div class=\"topic-heading\"><p class=\"eyebrow\">RELATIVE TURN SPACE</p><h3 id=\"turn-space-model-title\">Turn Circle周辺を読む3つの位置概念</h3></div>\n              </header>\n              <div class=\"zones-copy\">\n                <article><span>01</span><h3>Turn Bubble <small>現在の旋回限界を表す目安</small></h3><p>現在の速度と旋回能力から考える、機体がすぐには内側へ向きを変えられない空間の目安です。速度やエネルギーが変われば大きさも変わるため、固定された球ではありません。</p></article>\n                <article><span>02</span><h3>Control Zone <small>後方の管理領域</small></h3><p>相手の後方で、Range・Angles・Closureを同時に管理しやすい3次元の領域です。単に後ろへ入ることではなく、距離と角度と接近率が整っているかを確認します。</p></article>\n                <article><span>03</span><h3>Attack / Assessment Window <small>進入条件を確かめる手掛かり</small></h3><p>Control Zoneへ移る前に、Range・Angles・Closureが整うかを評価する位置や見え方の手掛かりです。名称・形・判定基準は資料や機種で異なるため、普遍的な一点として暗記しません。</p></article>\n              </div>\n              <p class=\"term-note turn-space-source-note\"><strong>用語上の注意</strong> Turn Bubble、Control Zone、Attack Windowは、訓練資料の目的や機種によって形と基準が変わります。この講座では数値や固定形状を置かず、2機の相対関係を整理するための概念として扱います。<a class=\"source-marker\" href=\"#ref-4\" aria-label=\"参考資料4へ\">[4]</a><a class=\"source-marker\" href=\"#ref-5\" aria-label=\"参考資料5へ\">[5]</a></p>\n            </section>\n            <section class=\"turn-circle-stage\" aria-labelledby=\"turn-circle-reading-title\">\n              <header class=\"turn-circle-stage-header\">\n                <p class=\"turn-circle-stage-marker\"><span>STEP</span><strong>03</strong><small>DECISION</small></p>\n                <div class=\"topic-heading\"><p class=\"eyebrow\">READING ORDER</p><h3 id=\"turn-circle-reading-title\">Turning Roomを判断する3つの手順</h3></div>\n              </header>\n              <ol class=\"zone-reading-order\" aria-label=\"Turning Roomを判断する順序\">\n                <li><span>01</span><div><b>2機の関係を読む</b><small>Range・Angles・Closureから、次に必要な修正を決めます。</small></div></li>\n                <li><span>02</span><div><b>使える空間を探す</b><small>左右だけでなく、上下を含むTurning Roomを見ます。</small></div></li>\n                <li><span>03</span><div><b>性能と交換条件を選ぶ</b><small>必要なRate／Radiusと、消費できるエネルギーを考えます。</small></div></li>\n              </ol>\n              <div class=\"warning-box callout callout-warning\"><span>注意</span><p>Turning Roomは自機だけのものではありません。空間を作れば相手にも利用される可能性があるため、2機の向きとClosureを再評価します。</p></div>\n            </section>\n          </div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Turning Roomは向きを変えるために使える空間、Turn Circleは現在の速度と荷重から生じる旋回の形です。<a class=\"source-marker\" href=\"#ref-1\" aria-label=\"参考資料1へ\">[1]</a></p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"pursuit\" data-section=\"Pursuit Curves\" aria-labelledby=\"pursuit-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>08</span></p>\n              <p class=\"mission-reveal-title\">Pursuit Curves</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"pursuit-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"pursuit-title\"><span class=\"module-title-number lesson-number\">08:</span><span class=\"module-title-text lesson-title-text\">Pursuit Curves</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>Lead・Pure・Lagを、機首を向ける場所とClosureの変化で比較する。</p>\n          </header>\n          <div class=\"comparison-cards card-grid three-up pursuit-comparison\">\n            <article>\n              <p class=\"term-en\">Lead Pursuit</p><p class=\"term-ja\">前方追跡</p>\n              <p>敵機の進行方向の<strong>前</strong>へ機首を向けます。</p>\n              <dl><div><dt>距離</dt><dd>縮みやすい</dd></div><div><dt>Closure</dt><dd>増えやすい</dd></div><div><dt>注意</dt><dd>Overshoot</dd></div></dl>\n            </article>\n            <article>\n              <p class=\"term-en\">Pure Pursuit</p><p class=\"term-ja\">純粋追跡</p>\n              <p>敵機の<strong>現在位置</strong>へ機首を向けます。</p>\n              <dl><div><dt>距離</dt><dd>状況による</dd></div><div><dt>Closure</dt><dd>状況による</dd></div><div><dt>注意</dt><dd>中立とは限らない</dd></div></dl>\n            </article>\n            <article>\n              <p class=\"term-en\">Lag Pursuit</p><p class=\"term-ja\">後方追跡</p>\n              <p>敵機の進行方向の<strong>後ろ</strong>へ機首を向けます。</p>\n              <dl><div><dt>距離</dt><dd>詰まりにくい</dd></div><div><dt>Closure</dt><dd>抑えやすい</dd></div><div><dt>注意</dt><dd>離れすぎ</dd></div></dl>\n            </article>\n          </div>\n          <figure class=\"reference-figure reference-figure-wide\">\n            <div class=\"reference-image-canvas reference-image-tall\"><img src=\"assets/reference-usn-pursuit-curves.png\" alt=\"旋回中の目標に対し、機首を目標の進行方向より前、目標そのもの、後方へ向けるLead・Pure・Lagの3種類の追跡を比較した図\" loading=\"lazy\"></div>\n            <figcaption class=\"compact-citation\"><a class=\"source-marker\" href=\"#ref-6\" aria-label=\"参考資料6へ\">[6]</a></figcaption>\n          </figure>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Leadは距離を詰め、Lagは詰まり方を抑え、Pureは相手そのものへ向けます。状況に応じて連続的に使い分けます。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"overshoot\" data-section=\"Overshoot\" aria-labelledby=\"overshoot-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>09</span></p>\n              <p class=\"mission-reveal-title\">Overshoot</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"overshoot-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"overshoot-title\"><span class=\"module-title-number lesson-number\">09:</span><span class=\"module-title-text lesson-title-text\">Overshoot</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>距離が詰まりすぎる原因と、相手の飛行経路を横切る結果をClosure管理と結びつける。</p>\n          </header>\n          <p class=\"lead-copy\">Overshoot（オーバーシュート）は、接近しすぎたり相手の飛行経路を越えたりして、有利な後方位置を保てなくなることです。大きすぎるClosure、長すぎるLead、高すぎる速度、相手の急旋回への遅れ、距離と角度の管理失敗が主な原因です。</p>\n          <div class=\"comparison-cards card-grid two-up overshoot-comparison\">\n            <article><span class=\"risk-tag\">CAUSE</span><p class=\"term-en\">EXCESS CLOSURE</p><h3>距離が急に詰まる</h3><p>Leadを長く使う、高い速度差を残すなどにより、相手との間隔を維持できなくなります。</p><small>見るもの：Rangeの変化とClosure</small></article>\n            <article><span class=\"risk-tag critical\">RESULT</span><p class=\"term-en\">FLIGHT-PATH OVERSHOOT</p><h3>飛行経路を横切る</h3><p>相手が進むと予測される経路を通過し、安定した追跡位置を失う状態です。</p><small>見るもの：相手の飛行経路と自機の機首位置</small></article>\n          </div>\n          <div class=\"bridge-note callout callout-bridge reversal-opportunity\"><span>REVERSAL OPPORTUNITY</span><p>攻撃側が飛行経路を越えると、防御側に旋回方向を変えて関係を作り直す機会が生まれる場合があります。ただし、Overshootが起きれば必ず逆転できるわけではありません。Range・HCA・Closureと、相手の飛行経路がどこへ移ったかを一緒に見て判断します。<a class=\"source-marker\" href=\"#ref-4\" aria-label=\"参考資料4へ\">[4]</a></p></div>\n          <div class=\"warning-box callout callout-warning\"><span>判断</span><p>距離が急に詰まり始めたら、相手の飛行経路を越えてから対応するのではなく、Lead・速度・旋回の強さを早めに再評価します。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Overshootは速度だけの問題ではありません。Range・Angles・Closureと追跡方法の組み合わせで起こります。<a class=\"source-marker\" href=\"#ref-4\" aria-label=\"参考資料4へ\">[4]</a></p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"alignment\" data-section=\"Turn Circle Alignment\" aria-labelledby=\"alignment-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>10</span></p>\n              <p class=\"mission-reveal-title\">Circle Alignment</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"alignment-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"alignment-title\"><span class=\"module-title-number lesson-number\">10:</span><span class=\"module-title-text lesson-title-text\">Circle Alignment</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>同じ方向へ旋回していても、旋回円が一致しないことを認識する。</p>\n          </header>\n          <p class=\"lead-copy\">Overshootで2機の飛行経路が交差したあとも、関係はそこで終わりません。次に見るのは、双方が描く旋回円の中心や運動面が一致しているか、それともずれているかです。</p>\n          <div class=\"comparison-cards card-grid two-up alignment-comparison\">\n            <article><span class=\"compare-tag\">ALIGNED</span><h3>中心がおおむね一致</h3><p>相対運動を読みやすく、安定した追跡状態を作りやすい状態です。</p><ol class=\"mini-flow\"><li>見かけの動きを観察</li><li>旋回円の位置を推定</li><li>追跡状態を再評価</li></ol></article>\n            <article><span class=\"compare-tag warning\">MISALIGNED</span><h3>中心または旋回面がずれる</h3><p>同じ方向へ旋回していても、上下動や横ずれが大きく見えることがあります。</p><ol class=\"mini-flow\"><li>ずれを認識</li><li>RangeとClosureを確認</li><li>引き続けるか再判断</li></ol></article>\n          </div>\n          <div class=\"advanced-box callout callout-advanced\"><span>ADVANCED</span><p>Misalignmentは常に不利とは限りません。相手が自機前方へ移動し、追加の大きなエネルギー消費なしに機会が生まれる場合もあります。初心者の目標は、まず「ずれている」と認識することです。</p></div>\n          <p class=\"term-note\"><strong>extend（延伸する）</strong>：一時的に敵機から距離を取り、位置関係やエネルギーを整えること。</p>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>同じ右旋回でも円は一致しません。見かけの上下動を手掛かりに、必要なら引き続けず、距離と位置を整えます。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"circle-fight\" data-section=\"One‑Circle / Two‑Circle\" aria-labelledby=\"circle-fight-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>11</span></p>\n              <p class=\"mission-reveal-title\">One / Two Circle</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"circle-fight-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"circle-fight-title\"><span class=\"module-title-number lesson-number\">11:</span><span class=\"module-title-text lesson-title-text\">One / Two Circle</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>形成される旋回空間・位置関係・重要になりやすい性能を比較する。</p>\n          </header>\n          <div class=\"bridge-note callout callout-bridge merge-bridge\"><span>START AT THE MERGE</span><p><strong>Merge（マージ）</strong>は、2機が近い位置ですれ違う局面です。その後にできる流れをOne‑CircleまたはTwo‑Circleとして読みます。操縦桿を左右どちらへ動かしたかだけではなく、2機の飛行経路が1つの旋回空間を共有するか、それぞれ別の旋回円を作るかを見ます。<a class=\"source-marker\" href=\"#ref-4\" aria-label=\"参考資料4へ\">[4]</a></p></div>\n          <figure class=\"reference-figure reference-figure-wide\">\n            <div class=\"reference-image-canvas reference-image-tall\"><img src=\"assets/reference-usn-circle-flow.png\" alt=\"上段は2機が一つの旋回円を形作るOne‑Circle、下段は各機が別々の旋回円を形作るTwo‑Circleを、赤と青の飛行経路で比較した図\" loading=\"lazy\"></div>\n            <figcaption class=\"compact-citation\"><a class=\"source-marker\" href=\"#ref-6\" aria-label=\"参考資料6へ\">[6]</a></figcaption>\n          </figure>\n          <div class=\"table-wrap\">\n            <table>\n              <caption>One‑CircleとTwo‑Circleの基本比較</caption>\n              <thead><tr><th>項目</th><th>One‑Circle</th><th>Two‑Circle</th></tr></thead>\n              <tbody>\n                <tr><th>形成される旋回空間</th><td>1つを共有</td><td>それぞれ別</td></tr>\n                <tr><th>重要な性能</th><td>Turn Radius</td><td>Turn Rate</td></tr>\n                <tr><th>別名</th><td>Radius Fight</td><td>Rate Fight</td></tr>\n                <tr><th>位置関係</th><td>Nose-to-nose</td><td>Nose-to-tail</td></tr>\n              </tbody>\n            </table>\n          </div>\n          <p class=\"term-note nose-on-note\"><strong>Nose-on / Sensor Nose On</strong>は、相手へ機首またはセンサーの有効方向を向けられる状態を表す言い方です。One‑Circleでは、より小さなTurn Radiusによって先にNose-onを作れる場合があります。ただしSensor Noseの範囲は搭載システムや資料によって異なるため、固定角度として扱いません。<a class=\"source-marker\" href=\"#ref-5\" aria-label=\"参考資料5へ\">[5]</a></p>\n          <div class=\"warning-box callout callout-warning\"><span>注意</span><p>「One‑Circleなら必ずこの機体が勝つ」という意味ではありません。初期位置・速度・エネルギー・操縦によって結果は変わります。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>One‑Circleは半径、Two‑Circleは持続旋回率が重要になりやすい——ただし、どちらも状況全体で判断します。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"plane-motion\" data-section=\"Plane of Motion\" aria-labelledby=\"plane-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>12</span></p>\n              <p class=\"mission-reveal-title\">Plane of Motion</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"plane-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"plane-title\"><span class=\"module-title-number lesson-number\">12:</span><span class=\"module-title-text lesson-title-text\">Plane of Motion</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>旋回円が置かれる「面」を理解し、2次元図の限界を知る。</p>\n          </header>\n          <p><strong>Plane of Motion（運動面）</strong>とは、機体が描く旋回円が置かれている面です。2機の面がほぼ同じならIn‑plane、一方が面を傾けて別の平面を使えばOut‑of‑planeです。</p>\n          <div class=\"comparison-cards card-grid two-up plane-comparison\">\n            <article><span class=\"compare-tag\">IN-PLANE</span><h3>ほぼ同じ運動面</h3><p>2機がほぼ同じ平面上で旋回する状態。上面の比較で関係を捉えやすい基本形です。</p><small>見るもの：同じ面内のRange・Angles・Closure</small></article>\n            <article><span class=\"compare-tag warning\">OUT-OF-PLANE</span><h3>異なる運動面</h3><p>一方が別の平面を使う状態。上面図だけでは高度方向のずれを表しきれません。</p><small>見るもの：上下方向を含む相対運動</small></article>\n          </div>\n          <p class=\"term-note relative-plane-note\"><strong>水平でも垂直でも判断軸は同じ</strong> 地平線に対して上か横かではなく、相手の飛行経路に対して自機がどの面へ動いているかを見ます。Range・Angles・Closure、Turn Rate・Radius、Lead・Pure・Lagは、水平面と垂直面のどちらでも相対関係を読むために使います。</p>\n          <div class=\"bridge-note callout callout-bridge\"><span>ADVANCED CONNECTION</span><p>Out‑of‑planeの理解は、上下方向にTurning Roomを作る応用機動へつながります。このページでは、実際の関係が3次元であることの認識までを扱います。</p></div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>実際の機動は3次元です。上面図は基礎を整理する道具であり、垂直方向を含むすべてを表すものではありません。<a class=\"source-marker\" href=\"#ref-4\" aria-label=\"参考資料4へ\">[4]</a></p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"guns\" data-section=\"射撃機会の基礎\" aria-labelledby=\"guns-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>13</span></p>\n              <p class=\"mission-reveal-title\">射撃機会の基礎</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"guns-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"guns-title\"><span class=\"module-title-number lesson-number\">13:</span><span class=\"module-title-text lesson-title-text\">射撃機会の基礎</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>安定追跡と一瞬の交差という、2つの射撃機会の違いを概念として理解する。</p>\n          </header>\n          <div class=\"safety-intro callout callout-scope\">\n            <span>EDUCATIONAL SCOPE</span>\n            <p>ここでは武器操作や照準手順ではなく、BFM上の位置関係だけを扱います。具体的な運用手順や機種固有の数値は扱いません。</p>\n          </div>\n          <div class=\"guns-grid card-grid\">\n            <article>\n              <h3>Tracking Guns Solution <small>継続追跡の機会</small></h3>\n              <p>敵機の動きに合わせて、照準位置に継続して捉えられる状態。Lead・適切なRange・相手の運動面との一致が必要です。</p>\n            </article>\n            <article>\n              <h3>Snapshot <small>一瞬の交差機会</small></h3>\n              <p>敵機が照準位置を短時間だけ横切る瞬間を利用する機会。未来位置の予測が必要で、安定した追跡ではなく、機会はごく短時間です。</p>\n            </article>\n          </div>\n          <div class=\"checkpoint callout callout-summary\"><strong>ここまでの要点</strong><p>Trackingは安定して追い続ける機会、Snapshotは一瞬の交差機会。どちらも位置関係の結果として生まれます。</p></div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"recap\" data-section=\"初心者が覚える要点\" aria-labelledby=\"recap-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>14</span></p>\n              <p class=\"mission-reveal-title\">初心者の要点</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"recap-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"recap-title\"><span class=\"module-title-number lesson-number\">14:</span><span class=\"module-title-text lesson-title-text\">初心者の要点</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>PART 01の判断軸を短い言葉で思い出せる。</p>\n          </header>\n          <div class=\"recap-panel\">\n            <ol class=\"recap-list\">\n              <li><span>01</span>BFMは固定された技の順番ではない</li><li><span>02</span>観察・予測・機動を循環させる</li>\n              <li><span>03</span>相手との相対位置を基準に考える</li><li><span>04</span>速度・高度と機首位置の交換を意識する</li>\n              <li><span>05</span>瞬間旋回と持続旋回を区別する</li><li><span>06</span>Range・Angles・Closureを同時に管理する</li>\n              <li><span>07</span>Aspect AngleとHCAを混同しない</li><li><span>08</span>Turning Room・Turn Circle・Control Zoneを区別する</li>\n              <li><span>09</span>Lead・Pure・Lagを使い分ける</li><li><span>10</span>Closureを管理してOvershootを防ぐ</li>\n              <li><span>11</span>旋回円のずれを認識する</li><li><span>12</span>One‑CircleとTwo‑Circleを区別する</li>\n              <li><span>13</span>運動面を3次元で考え、TrackingとSnapshotを区別する</li>\n            </ol>\n            <blockquote>BFMは、単に強く旋回する技術ではない。変化する2機の位置関係とエネルギーを読み、必要な位置へ動くための継続的な判断である。<a class=\"source-marker\" href=\"#ref-1\" aria-label=\"参考資料1へ\">[1]</a></blockquote>\n          </div>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"quiz\" data-section=\"確認問題\" aria-labelledby=\"quiz-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>15</span></p>\n              <p class=\"mission-reveal-title\">確認問題</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"quiz-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"quiz-title\"><span class=\"module-title-number lesson-number\">15:</span><span class=\"module-title-text lesson-title-text\">確認問題</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>学習目標</span>答えを選ぶだけでなく、解説から判断の理由を確認する。</p>\n          </header>\n          <div class=\"quiz-intro\">\n            <p>各問に回答すると、正解・正しい答え・短い解説・復習リンクが表示されます。</p>\n            <div><span>ANSWERED</span><strong id=\"quiz-answered\">0 / 12</strong></div>\n          </div>\n          <div id=\"quiz-list\" class=\"quiz-list\"></div>\n          <section class=\"quiz-result\" id=\"quiz-result\" hidden tabindex=\"-1\" aria-labelledby=\"quiz-result-title\">\n            <p class=\"section-code\">FINAL SCORE</p>\n            <h3 id=\"quiz-result-title\"><span id=\"quiz-score\">0</span> / 12</h3>\n            <p id=\"quiz-message\"></p>\n            <button class=\"button button-quiet\" id=\"quiz-reset\" type=\"button\">もう一度挑戦する</button>\n          </section>\n          <noscript><p class=\"warning-box callout callout-warning\">確認問題の自動採点にはJavaScriptが必要です。本文と各章の「ここまでの要点」はJavaScriptなしでも読めます。</p></noscript>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"glossary\" data-section=\"用語集\" aria-labelledby=\"glossary-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>16</span></p>\n              <p class=\"mission-reveal-title\">用語集</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"glossary-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"glossary-title\"><span class=\"module-title-number lesson-number\">16:</span><span class=\"module-title-text lesson-title-text\">用語集</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>使い方</span>英語・日本語・説明文から検索し、関連する学習章へ戻る。</p>\n          </header>\n          <div class=\"glossary-search\">\n            <label for=\"glossary-input\">用語を検索</label>\n            <div><span aria-hidden=\"true\">⌕</span><input id=\"glossary-input\" type=\"search\" placeholder=\"例：closure、接近率、旋回\" autocomplete=\"off\"><kbd>/</kbd></div>\n            <p><strong id=\"glossary-count\">0</strong> terms found</p>\n          </div>\n          <div id=\"glossary-list\" class=\"glossary-list\"></div>\n          <p id=\"glossary-empty\" class=\"empty-state\" hidden>一致する用語がありません。別の言葉で検索してください。</p>\n          <noscript><div class=\"noscript-glossary\"><h3>基本用語</h3><p>BFM＝基本戦闘機動 / Range＝距離 / Angles＝角度・位置関係 / Closure＝接近率 / Turn Rate＝旋回率 / Turn Radius＝旋回半径 / Overshoot＝有利な後方位置を越えて失うこと。</p></div></noscript>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"references\" data-section=\"参考資料\" aria-labelledby=\"references-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>17</span></p>\n              <p class=\"mission-reveal-title\">参考資料・出典</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"references-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"references-title\"><span class=\"module-title-number lesson-number\">17:</span><span class=\"module-title-text lesson-title-text\">参考資料・出典</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>方針</span>動画・公開資料・提供PDFの書誌情報と外部リンクを、この章へまとめる。</p>\n          </header>\n          <div class=\"source-notice callout callout-source\"><strong>資料の表示方針</strong><p>本文では小さな参照番号だけを表示し、動画、書誌情報、原典、作者、権利表示、外部リンクはこの章へ集約しています。提供PDFは文章の確認と要約にだけ使い、図版は転載していません。</p></div>\n          <ol class=\"references-list\">\n            <li id=\"ref-1\"><span>USER-PROVIDED MANUAL</span><div><h3>Republic of Korea Air Force — Basic Employment Manual F-16C</h3><p>『Korean Air Force Tactics, Techniques &amp; Procedures 3-3, Volume 5』、2005年10月1日。§4.3（印刷ページ4-12〜4-24）の目的、継続的な判断、位置関係、追跡、旋回とエネルギーを要約。本文では機種固有の数値・操作・図版を使用していません。</p></div><time datetime=\"2005-10-01\">発行日：2005-10-01</time></li>\n            <li id=\"ref-2\"><span>PUBLIC EDUCATION</span><div><h3>NASA Glenn Research Center — Guide to Aerodynamics</h3><p>揚力・抗力・推力・迎角・旋回などを扱う公式公開教材。本文のFour Forces図もNASA Glennが公開する教材図です。</p><a href=\"https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/learn-about-aerodynamics/\" target=\"_blank\" rel=\"noopener noreferrer\">NASA公式教材 <span aria-hidden=\"true\">↗</span></a> <a href=\"https://www1.grc.nasa.gov/beginners-guide-to-aeronautics/four-forces-on-an-airplane/\" target=\"_blank\" rel=\"noopener noreferrer\">Four Forces図 <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-07-31\">参照日：2026-07-31</time></li>\n            <li id=\"ref-3\"><span>PUBLIC HANDBOOK</span><div><h3>Federal Aviation Administration — Aeronautical Handbooks</h3><p>『Pilot’s Handbook of Aeronautical Knowledge』Chapter 5と、『Airplane Flying Handbook』Chapter 3の旋回率・旋回半径の説明を参照。</p><a href=\"https://www.faa.gov/regulations_policies/handbooks_manuals/aviation/phak\" target=\"_blank\" rel=\"noopener noreferrer\">PHAK公式ページ <span aria-hidden=\"true\">↗</span></a> <a href=\"https://www.faa.gov/sites/faa.gov/files/regulations_policies/handbooks_manuals/aviation/airplane_handbook/04_afh_ch3.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">AFH Chapter 3 <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-07-31\">参照日：2026-07-31</time></li>\n            <li id=\"ref-4\"><span>OFFICIAL PUBLICATION</span><div><h3>U.S. Air Force — AETCTTP 11-1</h3><p>BFM Geometry、AOT、Turn Radius、Control Zone、Overshoot、Reversal、Merge、Plane of Motionなどの用語と概念を参照。T-38C／IFF固有の性能値は一般化していません。</p><a href=\"https://static.e-publishing.af.mil/production/1/aetc/publication/aetcttp11-1/aetcttp11-1.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">公式PDF <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-08-04\">参照日：2026-08-04</time></li>\n            <li id=\"ref-5\"><span>OFFICIAL CURRICULUM</span><div><h3>U.S. Navy, Chief of Naval Air Training — CNATRAINST 1542.167B</h3><p>Attack Window、Attack Window Entry、BFMなど、訓練課程で使われる用語を確認。本文では機種・課程固有の角度、距離、手順を一般化せず、資料によって定義が変わる用語として説明しています。</p><a href=\"https://www.cnatra.navy.mil/local/docs/mcg/1542.167.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">公式PDF <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-08-04\">参照日：2026-08-04</time></li>\n            <li id=\"ref-6\"><span>PUBLIC DOMAIN IMAGES</span><div><h3>U.S. Navy, Naval Air Training Command</h3><p>CNATRA P-825の追跡曲線図と、CNATRA P-1289のCircle flow図。米国連邦政府の職務著作物としてPublic Domainと表示されています。</p><a href=\"https://commons.wikimedia.org/wiki/File:Pursuit_curves_in_air_combat.PNG\" target=\"_blank\" rel=\"noopener noreferrer\">Pursuit curves <span aria-hidden=\"true\">↗</span></a> <a href=\"https://commons.wikimedia.org/wiki/File:Circle_flow_in_air_combat.png\" target=\"_blank\" rel=\"noopener noreferrer\">Circle flow <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-07-31\">参照日：2026-07-31</time></li>\n            <li id=\"ref-7\"><span>VIDEO / SERIES</span><div><h3>DCS - Introduction to BFM (Basic Fighter Manoeuvres)</h3><p>独立クリエイターDCS Debriefによるゲーム環境向け解説で、Eagle Dynamicsの公式教材ではありません。続編は「Fundamentals 02 - Turning」「03 - Pursuit」「04 - Basic flows」。</p><a id=\"dcs-debriefs-link\" href=\"https://www.youtube.com/watch?v=BCh1UxXnBiE\" target=\"_blank\" rel=\"noopener noreferrer\">Introduction <span aria-hidden=\"true\">↗</span></a> <a href=\"https://www.youtube.com/watch?v=n9XW1Q7YypM\" target=\"_blank\" rel=\"noopener noreferrer\">02 Turning <span aria-hidden=\"true\">↗</span></a> <a href=\"https://www.youtube.com/watch?v=6hTps0bIi2I\" target=\"_blank\" rel=\"noopener noreferrer\">03 Pursuit <span aria-hidden=\"true\">↗</span></a> <a href=\"https://www.youtube.com/watch?v=ZkXKYzGfxGE\" target=\"_blank\" rel=\"noopener noreferrer\">04 Basic flows <span aria-hidden=\"true\">↗</span></a> <a href=\"https://www.youtube.com/@DCSDebrief\" target=\"_blank\" rel=\"noopener noreferrer\">チャンネル <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-07-31\">参照日：2026-07-31</time></li>\n            <li id=\"ref-8\"><span>BOOK</span><div><h3>Fighter Combat: Tactics and Maneuvering</h3><p>Robert L. Shaw 著、Naval Institute Press、1985年。ISBN 978-0-87021-059-4。</p><a href=\"https://books.google.com/books/about/Fighter_Combat.html?id=hBxBdKr0beYC\" target=\"_blank\" rel=\"noopener noreferrer\">Google Books書誌 <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-07-31\">参照日：2026-07-31</time></li>\n            <li id=\"ref-9\"><span>OFFICIAL DOCS</span><div><h3>Eagle Dynamics SA — Documentation</h3><p>DCS Worldの公式文書一覧と「DCS User Manual」。</p><a href=\"https://www.digitalcombatsimulator.com/en/downloads/documentation/?SHOWALL_1=1\" target=\"_blank\" rel=\"noopener noreferrer\">公式文書一覧 <span aria-hidden=\"true\">↗</span></a> <a href=\"https://www.digitalcombatsimulator.com/en/downloads/documentation/dcs-user_manual_en/\" target=\"_blank\" rel=\"noopener noreferrer\">DCS User Manual <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-07-31\">参照日：2026-07-31</time></li>\n            <li id=\"ref-10\"><span>MEDIA POLICY</span><div><h3>NASA — Images and Media Usage Guidelines</h3><p>NASA画像の教育・情報目的での利用条件と、NASAによる推奨・提携を示してはならない旨を確認しています。</p><a href=\"https://www.nasa.gov/nasa-brand-center/images-and-media/\" target=\"_blank\" rel=\"noopener noreferrer\">利用ガイドライン <span aria-hidden=\"true\">↗</span></a></div><time datetime=\"2026-07-31\">参照日：2026-07-31</time></li>\n          </ol>\n          <p class=\"citation-note\">本文の重要概念は、上記の公開資料とユーザー提供PDFを基に初心者向けに要約しています。特定機種の性能値や実機の操作手順は扱っていません。</p>\n        </section>\n      </section>\n\n      <section class=\"mission-sequence\" id=\"next\" data-section=\"Next Part\" aria-labelledby=\"next-title\">\n        <div class=\"mission-reveal\" data-mission-reveal aria-hidden=\"true\">\n          <div class=\"mission-reveal-sticky\">\n            <div class=\"mission-reveal-grid\"></div>\n            <div class=\"mission-reveal-copy\">\n              <p class=\"mission-reveal-label\">MISSION <span>18</span></p>\n              <p class=\"mission-reveal-title\">Next Part</p>\n            </div>\n            <p class=\"mission-reveal-cue\"><span></span>SCROLL TO CONTINUE</p>\n          </div>\n        </div>\n        <section class=\"module\" data-mission-content aria-labelledby=\"next-title\">\n          <header class=\"module-header lesson-header\">\n            <div><h2 class=\"numbered-module-title lesson-title\" id=\"next-title\"><span class=\"module-title-number lesson-number\">18:</span><span class=\"module-title-text lesson-title-text\">Next Part</span></h2></div>\n            <p class=\"learning-goal lesson-goal\"><span>選択</span>基礎を修了したあとに、次に学ぶ講座を選ぶ。</p>\n          </header>\n          <div class=\"next-panel course-selector\">\n            <div class=\"course-completion\">\n              <div><p class=\"section-code\">FOUNDATION COMPLETE</p><h3>次に学ぶ講座を選ぶ</h3></div>\n              <span class=\"badge badge-live\">PART 01 修了</span>\n            </div>\n            <p class=\"lead-copy\">ここから先は、同じ基礎を異なる立場から使います。どちらを選んでも、まずRange・Angles・Closure、エネルギー、追跡曲線の理解が土台になります。</p>\n            <div class=\"course-choice-grid card-grid\" aria-label=\"次に学ぶ講座\">\n              <article class=\"course-choice content-card course-card\" id=\"course-offensive\" aria-disabled=\"true\">\n                <div class=\"course-choice-meta\"><span>COURSE 02</span><span class=\"badge\">準備中</span></div>\n                <h3>Offensive BFM</h3>\n                <p>相手の後方から始め、Range・Angles・ClosureとLead／Pure／Lagを使い分けて、安定した位置条件へ進む考え方を学びます。</p>\n                <ul class=\"compact-list\"><li>追跡曲線の選択</li><li>Closureの管理</li><li>有利な位置の維持</li></ul>\n                <button class=\"button button-primary\" type=\"button\" disabled>公開準備中</button>\n              </article>\n              <article class=\"course-choice content-card course-card\" id=\"course-defensive\" aria-disabled=\"true\">\n                <div class=\"course-choice-meta\"><span>COURSE 03</span><span class=\"badge\">準備中</span></div>\n                <h3>Defensive BFM</h3>\n                <p>不利な位置から始め、相手の機会を成立させず、追跡・距離・エネルギーに問題を作って中立化や離脱を目指す考え方を学びます。</p>\n                <ul class=\"compact-list\"><li>最初の機会を拒む</li><li>Overshootを誘う</li><li>中立化・離脱を判断する</li></ul>\n                <button class=\"button button-primary\" type=\"button\" disabled>公開準備中</button>\n              </article>\n            </div>\n            <p class=\"no-figure-note callout callout-status\"><span>COURSE STATUS</span>2つの発展講座は準備中です。公開後は、この2枚のカードから進む講座を選べるようになります。</p>\n          </div>\n        </section>\n      </section>\n    </article>\n  </div>\n</main>\n\n<footer class=\"site-footer\">\n    <div class=\"footer-brand\"><span class=\"brand-mark\" aria-hidden=\"true\">B</span><div><strong>BFM Japan</strong><p>FLIGHT GEOMETRY FOR BEGINNERS</p></div></div>\n    <div class=\"disclaimer\">\n      <h2>教育目的・ご利用上の注意</h2>\n      <ul>\n        <li>航空・フライトシミュレーターに関する教育用コンテンツであり、実際の軍事作戦や実機操縦訓練を目的としません。</li>\n        <li>公開情報を初心者向けに簡略化し、引用図には原典・作者・権利表示へのリンクを付けています。</li>\n        <li>性能は搭載物・重量・高度・速度・シミュレーターの版などで変わります。数値や図を絶対的なものとして扱わないでください。</li>\n        <li>武器に関する内容は、位置関係を理解するための教育用概念に限定しています。</li>\n      </ul>\n    </div>\n    <div class=\"footer-bottom\"><span>© 2026 BFM Japan</span><a href=\"#top\">PAGE TOP ↑</a></div>\n  </footer>";
